on conflict (id) do update set
name=excluded.name, slug=excluded.slug, category=excluded.category, location=excluded.location,
latitude=excluded.latitude, longitude=excluded.longitude, description=excluded.description,
image=excluded.image, opening_time=excluded.opening_time, closing_time=excluded.closing_time,
best_season=excluded.best_season, specialty=excluded.specialty, entry_fee=excluded.entry_fee,
visit_duration=excluded.visit_duration;
